--- a/packages/workflow/src/expressions/native-evaluation/evaluator.ts
+++ b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
@@ -508,6 +508,14 @@ function evalNodeRefCall(proxy: unknown, method: string, env: Env): unknown {
 	if (typeof fn !== 'function') throw new EngineFallbackError();

 	const result = bounded(fn.call(proxy));
+
+	// Anything that is not an item (or an array of items) is the engine's to resolve.
+	const isItem = (value: unknown) =>
+		typeof value === 'object' && value !== null && 'json' in value;
+	if (!(isArray(result) ? result.every(isItem) : isItem(result))) {
+		throw new EngineFallbackError();
+	}
+
 	env.charge(isArray(result) ? result.length : 1);

 	return result;
